1	package televibe
2	
3	import (
4		"context"
5		"fmt"
6		"log/slog"
7		"sync"
8		"time"
9	
10		"github.com/gravitational/teleport/api/client"
11		"github.com/gravitational/teleport/api/types"
12		"golang.org/x/sync/errgroup"
13	
14		"televibe/ai"
15		"televibe/jira"
16		"televibe/reputation"
17		"televibe/risk"
18		"televibe/telemetry"
19	)
20	
21	type App struct {
22		cfg    *Config
23		tele   *client.Client
24		ai     ai.Provider
25		jira   *jira.Client
26		scorer *risk.Scorer
27		rep    *reputation.Store
28		meter  *telemetry.Meter
29	
30		pending   map[string]string
31		pendingMu sync.Mutex
32	}
33	
34	func NewApp(ctx context.Context, cfg *Config) (*App, error) {
35		tele, err := client.New(ctx, client.Config{
36			Addrs: []string{cfg.Teleport.Addr},
37			Credentials: []client.Credentials{
38				client.LoadIdentityFile(cfg.Teleport.IdentityFile),
39			},
40		})
41		if err != nil {
42			return nil, fmt.Errorf("teleport client: %w", err)
43		}
44	
45		prov, err := ai.New(cfg.AI)
46		if err != nil {
47			return nil, fmt.Errorf("ai provider: %w", err)
48		}
49	
50		jc, err := jira.New(cfg.Jira)
51		if err != nil {
52			return nil, fmt.Errorf("jira client: %w", err)
53		}
54	
55		scorer, err := risk.NewScorer(cfg.Risk)
56		if err != nil {
57			return nil, fmt.Errorf("scorer: %w", err)
58		}
59	
60		store, err := reputation.NewStore(cfg.Reputation)
61		if err != nil {
62			return nil, fmt.Errorf("reputation store: %w", err)
63		}
64	
65		var meter *telemetry.Meter
66		if cfg.Telemetry.Enabled {
67			meter, err = telemetry.New(ctx, cfg.Telemetry, store)
68			if err != nil {
69				return nil, fmt.Errorf("telemetry: %w", err)
70			}
71		}
72	
73		return &App{
74			cfg:     cfg,
75			tele:    tele,
76			ai:      prov,
77			jira:    jc,
78			scorer:  scorer,
79			rep:     store,
80			meter:   meter,
81			pending: map[string]string{},
82		}, nil
83	}
84	
85	// Close flushes outstanding telemetry. Safe to call even if telemetry
86	// is disabled.
87	func (a *App) Close(ctx context.Context) error {
88		return a.meter.Shutdown(ctx)
89	}
90	
91	func (a *App) Run(ctx context.Context) error {
92		slog.Info("televibe starting",
93			"provider", a.cfg.AI.Provider,
94			"threshold", a.cfg.Risk.TicketThreshold,
95			"itsm_project", a.cfg.Jira.Project)
96	
97		if err := a.rehydrate(ctx); err != nil {
98			return fmt.Errorf("rehydrate open ITSM tickets: %w", err)
99		}
100	
101		// Run watcher/poller under their own cancelable context rather than
102		// bolting them directly to the signal context. A coordinator
103		// goroutine waits for the signal, then sleeps for
104		// telemetry.shutdown_grace before cancelling the errgroup so that
105		// the OTel periodic reader can finish an in-flight export cleanly.
106		runCtx, cancelRun := context.WithCancel(context.Background())
107		defer cancelRun()
108		g, gctx := errgroup.WithContext(runCtx)
109		g.Go(func() error { return a.watchRequests(gctx) })
110		g.Go(func() error { return a.pollITSM(gctx) })
111		g.Go(func() error {
112			select {
113			case <-ctx.Done():
114				grace := time.Duration(0)
115				if a.cfg.Telemetry.Enabled {
116					grace = a.cfg.Telemetry.ShutdownGrace
117				}
118				if grace > 0 {
119					slog.Info("shutdown signal received; waiting for telemetry flush", "grace", grace)
120					select {
121					case <-time.After(grace):
122					case <-gctx.Done():
123						// errgroup collapsed for some other reason; stop waiting.
124					}
125				}
126				cancelRun()
127			case <-gctx.Done():
128			}
129			return nil
130		})
131	
132		return g.Wait()
133	}
134	
135	func (a *App) rehydrate(ctx context.Context) error {
136		open, err := a.jira.ListOpenTeleportTickets(ctx)
137		if err != nil {
138			return err
139		}
140		a.pendingMu.Lock()
141		for reqID, ticket := range open {
142			a.pending[reqID] = ticket
143		}
144		a.pendingMu.Unlock()
145		slog.Info("rehydrated pending tickets", "count", len(open))
146		return nil
147	}
148	
149	func (a *App) watchRequests(ctx context.Context) error {
150		watcher, err := a.tele.NewWatcher(ctx, types.Watch{
151			Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
152		})
153		if err != nil {
154			return fmt.Errorf("start watcher: %w", err)
155		}
156		defer watcher.Close()
157	
158		for {
159			select {
160			case <-ctx.Done():
161				return ctx.Err()
162			case <-watcher.Done():
163				return watcher.Error()
164			case ev := <-watcher.Events():
165				if ev.Type != types.OpPut {
166					continue
167				}
168				req, ok := ev.Resource.(types.AccessRequest)
169				if !ok {
170					continue
171				}
172				if req.GetState() != types.RequestState_PENDING {
173					continue
174				}
175				if !a.reserveOrSkip(req.GetName()) {
176					continue
177				}
178				go a.handleRequest(ctx, req)
179			}
180		}
181	}
182	
183	// reserveOrSkip atomically claims a slot for request id. Returns true if
184	// this caller won the race and should process the request; false if the
185	// id is already in flight or already has a ticket. Using the same map
186	// for both reservations and ticket mappings keeps dedup decisions on a
187	// single source of truth.
188	func (a *App) reserveOrSkip(id string) bool {
189		a.pendingMu.Lock()
190		defer a.pendingMu.Unlock()
191		if _, held := a.pending[id]; held {
192			return false
193		}
194		a.pending[id] = ""
195		return true
196	}
197	
198	func (a *App) releasePending(id string) {
199		a.pendingMu.Lock()
200		defer a.pendingMu.Unlock()
201		delete(a.pending, id)
202	}
203	
204	func (a *App) recordTicket(id, ticket string) {
205		a.pendingMu.Lock()
206		defer a.pendingMu.Unlock()
207		a.pending[id] = ticket
208	}
209	
210	func (a *App) handleRequest(ctx context.Context, req types.AccessRequest) {
211		id := req.GetName()
212		user := req.GetUser()
213		log := slog.With("request_id", id, "user", user)
214	
215		// Release the reservation unless we successfully record a ticket;
216		// that way score/Jira failures are re-tryable on the next OpPut and
217		// auto-approved requests don't leave stale entries behind.
218		handled := false
219		defer func() {
220			if !handled {
221				a.releasePending(id)
222			}
223		}()
224	
225		log.Info("scoring access request")
226		result, err := a.scorer.Score(ctx, a.ai, req)
227		if err != nil {
228			log.Error("scoring failed", "err", err)
229			return
230		}
231		log.Info("risk scored",
232			"score", result.Score,
233			"tier", result.Tier.Name,
234			"components", result.Components)
235	
236		assessment, err := a.rep.Assess(ctx, user, result.Components)
237		if err != nil {
238			log.Warn("reputation update failed", "err", err)
239		}
240		if len(assessment.Penalties) > 0 {
241			reasons := make([]string, 0, len(assessment.Penalties))
242			for _, p := range assessment.Penalties {
243				reasons = append(reasons, p.Reason)
244			}
245			log.Info("reputation docked",
246				"previous", assessment.Previous,
247				"current", assessment.Score,
248				"reasons", reasons)
249		}
250	
251		threshold := a.cfg.Risk.TicketThreshold
252		if result.Escalation {
253			threshold = a.cfg.Risk.EscalationThresholdFor(req.GetRoles())
254			log.Info("session escalation detected", "threshold", threshold)
255		}
256	
257		if result.Score < threshold {
258			reason := fmt.Sprintf("televibe: %s (score %d) — auto-approved",
259				result.Tier.Name, result.Score)
260			if err := a.submitReview(ctx, id, types.RequestState_APPROVED, reason); err != nil {
261				log.Error("auto-approve failed", "err", err)
262				return
263			}
264			log.Info("access request auto-approved",
265				"score", result.Score,
266				"tier", result.Tier.Name,
267				"threshold", threshold)
268			return
269		}
270	
271		ticket, err := a.jira.CreateITSMTicket(ctx, jira.TicketInput{
272			RequestID:   id,
273			User:        req.GetUser(),
274			Roles:       req.GetRoles(),
275			Reason:      req.GetRequestReason(),
276			Score:       result.Score,
277			Tier:        result.Tier.Name,
278			Components:  result.Components,
279			AIReasoning: result.Reasoning,
280			Escalation:  result.Escalation,
281		})
282		if err != nil {
283			log.Error("create ITSM ticket failed", "err", err)
284			return
285		}
286	
287		a.recordTicket(id, ticket)
288		handled = true
289		log.Info("ITSM ticket created, request held for SRE review",
290			"ticket", ticket, "tier", result.Tier.Name)
291	}
292	
293	func (a *App) pollITSM(ctx context.Context) error {
294		t := time.NewTicker(a.cfg.Jira.PollInterval)
295		defer t.Stop()
296		for {
297			select {
298			case <-ctx.Done():
299				return ctx.Err()
300			case <-t.C:
301				a.reconcileITSM(ctx)
302			}
303		}
304	}
305	
306	func (a *App) reconcileITSM(ctx context.Context) {
307		a.pendingMu.Lock()
308		snap := make(map[string]string, len(a.pending))
309		for k, v := range a.pending {
310			snap[k] = v
311		}
312		a.pendingMu.Unlock()
313	
314		for requestID, ticket := range snap {
315			if ticket == "" {
316				// Reservation for an in-flight handleRequest; nothing to poll yet.
317				continue
318			}
319			status, err := a.jira.TicketStatus(ctx, ticket)
320			if err != nil {
321				slog.Warn("ITSM status check failed", "ticket", ticket, "err", err)
322				continue
323			}
324			var next types.RequestState
325			switch status {
326			case jira.StatusApproved:
327				next = types.RequestState_APPROVED
328			case jira.StatusRejected:
329				next = types.RequestState_DENIED
330			default:
331				continue
332			}
333			reason := fmt.Sprintf("televibe: ITSM %s resolved (%s)", ticket, status)
334			if err := a.submitReview(ctx, requestID, next, reason); err != nil {
335				slog.Error("submit review failed", "request_id", requestID, "err", err)
336				continue
337			}
338			a.pendingMu.Lock()
339			delete(a.pending, requestID)
340			a.pendingMu.Unlock()
341		}
342	}
343	
344	func (a *App) submitReview(ctx context.Context, requestID string, state types.RequestState, reason string) error {
345		_, err := a.tele.SubmitAccessReview(ctx, types.AccessReviewSubmission{
346			RequestID: requestID,
347			Review: types.AccessReview{
348				Author:        "televibe",
349				ProposedState: state,
350				Reason:        reason,
351			},
352		})
353		return err
354	}
