// submit is a tiny helper for the local test harness — fires a Teleport
// access request as a given user, so you can watch televibe score it.
//
// Usage:
//
//	go run ./cmd/submit --reason "plz"
//	go run ./cmd/submit --reason "CUSTX-1234 fix prod-api latency regression"
package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/gravitational/teleport/api/client"
	"github.com/gravitational/teleport/api/types"
)

func main() {
	addr := flag.String("addr", "localhost:3025", "teleport proxy address")
	identity := flag.String("identity", "./local/identity/charles.pem", "identity file")
	user := flag.String("user", "charles", "requesting user")
	roles := flag.String("roles", "privileged", "comma-separated roles to request")
	reason := flag.String("reason", "", "request reason")
	flag.Parse()

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	c, err := client.New(ctx, client.Config{
		Addrs:                    []string{*addr},
		Credentials:              []client.Credentials{client.LoadIdentityFile(*identity)},
		InsecureAddressDiscovery: true,
	})
	if err != nil {
		log.Fatalf("connect: %v", err)
	}
	defer c.Close()

	roleList := strings.Split(*roles, ",")
	req, err := types.NewAccessRequest(uuid.NewString(), *user, roleList...)
	if err != nil {
		log.Fatalf("new access request: %v", err)
	}
	req.SetRequestReason(*reason)

	created, err := c.CreateAccessRequestV2(ctx, req)
	if err != nil {
		log.Fatalf("create access request: %v", err)
	}
	fmt.Printf("submitted request %s — user=%s roles=%v reason=%q\n",
		created.GetName(), *user, roleList, *reason)
}

