func newReqWithAnnotations(t *testing.T, roles []string, annotations map[string][]string) types.AccessRequest {
	t.Helper()
	req, err := types.NewAccessRequest("test-req", "alice", roles...)
	if err != nil {
		t.Fatalf("new access request: %v", err)
	}
	if annotations != nil {
		req.SetSystemAnnotations(annotations)
	}
	return req
}

func TestIsEscalation(t *testing.T) {
	cases := []struct {
		name        string
		key         string
		annotations map[string][]string
		want        bool
	}{
		{name: "empty key", key: "", annotations: map[string][]string{"televibe.escalation": {"true"}}, want: false},
		{name: "no annotation", key: "televibe.escalation", annotations: nil, want: false},
		{name: "key present, empty value", key: "televibe.escalation", annotations: map[string][]string{"televibe.escalation": {""}}, want: false},
		{name: "key present with true", key: "televibe.escalation", annotations: map[string][]string{"televibe.escalation": {"true"}}, want: true},
		{name: "key present with arbitrary non-empty", key: "televibe.escalation", annotations: map[string][]string{"televibe.escalation": {"yes-please"}}, want: true},
		{name: "unrelated key set", key: "televibe.escalation", annotations: map[string][]string{"other": {"true"}}, want: false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			req := newReqWithAnnotations(t, []string{"role-a"}, tc.annotations)
			if got := IsEscalation(req, tc.key); got != tc.want {
				t.Errorf("IsEscalation = %v, want %v", got, tc.want)
			}
		})
	}
}

func TestEscalationThresholdFor(t *testing.T) {
	cfg := Config{
		EscalationThreshold: 15,
		EscalationThresholds: map[string]int{
			"sre-admin": 5,
			"db-admin":  10,
			"loose":     25,
		},
	}

	cases := []struct {
		name  string
		roles []string
		want  int
	}{
		{name: "no roles uses global", roles: nil, want: 15},
		{name: "unknown role uses global", roles: []string{"unknown"}, want: 15},
