		{name: "strictest among mixed wins", roles: []string{"loose", "db-admin", "sre-admin"}, want: 5},
		{name: "known plus unknown picks min of override and global", roles: []string{"loose", "unknown"}, want: 15},
	}

	for _, tc := range cases {
